import{_t as e,it as t,n,rt as r}from"./chunks/framework.D2cFUyj2.js";var i=JSON.parse(`{"title":"History","description":"","frontmatter":{},"headers":[{"level":2,"title":"1. Search History","slug":"_1-search-history","link":"#_1-search-history","children":[]},{"level":2,"title":"2. Keyword History","slug":"_2-keyword-history","link":"#_2-keyword-history","children":[]},{"level":2,"title":"3. Query Associations","slug":"_3-query-associations","link":"#_3-query-associations","children":[]}],"relativePath":"user-guide/settings/history.md","filePath":"user-guide/settings/history.md","lastUpdated":1792776074000}`),a={name:`user-guide/settings/history.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="history" tabindex="-1">History <a class="header-anchor" href="#history" aria-label="Permalink to “History”">​</a></h1><p>The History settings page manages usage frequency, typed search terms, and confirmed query-to-target associations across three independent tabs: <strong>Search History</strong>, <strong>Keyword History</strong>, and <strong>Query Associations</strong>.</p><h2 id="_1-search-history" tabindex="-1">1. Search History <a class="header-anchor" href="#_1-search-history" aria-label="Permalink to “1. Search History”">​</a></h2><p>Search History tracks how often and recently you open each file, folder, or application so direct matches break ties intelligently:</p><ul><li><strong>Decayed Frecency Tie-Breaking</strong>: Frequently opened items refine order <strong>within the same match grade</strong> using a 90-day half-life decay, without letting stale opens leapfrog an exact direct title or filename match.</li><li><strong>Inline Window Grouping</strong>: Inside file dialogs, matching items within the active folder appear under &quot;Current Folder&quot;, while others appear under &quot;Global Search&quot;.</li><li><strong>Dead Link Filtering</strong>: If an indexed path is moved or deleted, Lertaro automatically skips missing entries, guaranteeing unique rows.</li><li><strong>Management Controls</strong>: <ul><li><strong>Enable History</strong>: Master toggle; existing entries are retained when disabled. New entries are not added, while reopening an existing entry refreshes its recency.</li><li><strong>Search Filter</strong>: Narrows the visible history list by keyword.</li><li><strong>Usage Counts &amp; Cleanup</strong>: Each row shows how many times it has been opened. Choose a threshold and click <strong>Clear with at most N uses</strong> to remove low-use entries, or remove individual rows and click <strong>Clear All History</strong> to wipe everything.</li><li><strong>Live Updates</strong>: The list refreshes automatically when another search window records a new launch.</li></ul></li></ul><h2 id="_2-keyword-history" tabindex="-1">2. Keyword History <a class="header-anchor" href="#_2-keyword-history" aria-label="Permalink to “2. Keyword History”">​</a></h2><p>Keyword History remembers the <strong>raw query strings</strong> that were actually used to execute a result or action, or to open the Full Window. Merely typing a query and dismissing or leaving the Quick Window does not add it:</p><ul><li><strong>Hotkey Navigation</strong>: Inside the Quick Window, press <strong><code>Alt+Up</code></strong> / <strong><code>Alt+Down</code></strong> to cycle backward and forward through recent queries. Press <strong><code>Ctrl+Delete</code></strong> to delete the currently active term.</li><li><strong>Usage Counts &amp; Cleanup</strong>: Each keyword shows how many times it has been used. Choose a threshold and click <strong>Clear with at most N uses</strong> to remove low-use keywords.</li><li><strong>Independent Maintenance</strong>: Includes its own <strong>Enable History</strong> toggle, search filter, single-entry deletion, and <strong>Clear All History</strong> button. When disabled, existing keywords still accumulate usage counts, while new keywords are not added.</li></ul><h2 id="_3-query-associations" tabindex="-1">3. Query Associations <a class="header-anchor" href="#_3-query-associations" aria-label="Permalink to “3. Query Associations”">​</a></h2><p>Query Associations stores confirmed <strong>query → target path</strong> habits separately from general path frequency:</p><ul><li><strong>3-Open Confirmation Threshold</strong>: An item is recalled for a non-matching query only after you organically open it at least <strong>3 times</strong> for that normalized query, preventing one-off misclicks from polluting future searches.</li><li><strong>No Feedback Loops &amp; Monotonic Placement</strong>: Launching an item from learned recall alone never self-reinforces unconfirmed counts, excludes <code>Low</code>-priority cache paths, and always places learned recall after direct matches.</li><li><strong>Independent Cleanup</strong>: Filter, delete individual associations, or clear all learned associations at any time without resetting your path usage counts.</li></ul>`,11)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};